import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';

it('includes the budget-ending provider call in turn usage (specs/hal-engine-turn-usage/spec.md#2)', async () => {
  let calls = 0;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      calls++;
      yield {type: 'tool_use', toolCall: {id: "'`lookup-${calls}`, name: '"'lookup', input: {}}};
      yield {
        type: 'stop',
        stopReason: 'tool_use',
        usage: {inputTokens: calls * 2, outputTokens: calls, totalTokens: calls * 3},
      };
    },
    async generateStructured<T>(): Promise<T> {
      throw new Error('Structured generation is unused');
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'Look up a value', inputSchema: {type: 'object'}}, async () => 'found');
  const reports: Array<UsageMetadata | undefined> = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Usage test'}), registry, {
    maxToolRounds: 1,
    hooks: {
      afterModelResponse: async (_session, _text, usage) => {
        reports.push(usage);
      },
    },
  });

  await orchestrator.processMessage({sessionId: 'usage', userId: 'user', entries: []});

  expect({calls, reports}).toEqual({
    calls: 2,
    reports: [{inputTokens: 6, outputTokens: 3, totalTokens: 9}],
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/turnUsageHook.test.ts --runInBand"
